                stack = [(r, c)]
                visited.add((r, c))
                min_r, max_r = r, r
                min_c, max_c = c, c

                block_cells = []
                while stack:
                    curr_r, curr_c = stack.pop()
                    block_cells.append((curr_r, curr_c))
                    min_r = min(min_r, curr_r)
                    max_r = max(max_r, curr_r)
                    min_c = min(min_c, curr_c)
                    max_c = max(max_c, curr_c)

                    for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                        nr, nc = curr_r + dr, curr_c + dc
                        if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == val and (nr, nc) not in visited:
                            visited.add((nr, nc))
                            stack.append((nr, nc))

                # Filter for substantial rectangular blocks
                if len(block_cells) >= 4:
                    center_r = (min_r + max_r) / 2
                    center_c = (min_c + max_c) / 2
                    blocks.append({
                        'val': val,
                        'r': center_r,
                        'c': center_c
                    })

    if not blocks:
        return [[0]]

    # Extract all center coordinates
    all_r = sorted(list(set([b['r'] for b in blocks])))
    all_c = sorted(list(set([b['c'] for b in blocks])))

    # Helper to cluster into groups
    def cluster(coords, max_dist):
        if not coords:
