                clusters.append([val])
            else:
                clusters[-1].append(val)
        return [sum(g)/len(g) for g in clusters]

    # Dynamically find row and col bands
    # Try different thresholds to get either 2 or 3 rows, and 3 columns
    r_bands = []
    for dist in [15, 10, 8, 5, 3, 1]:
